import { Database } from "bun:sqlite"
import { readFile } from "node:fs/promises"
import { join } from "node:path"

const WORKFLOW_ID = "eval-worker-methodology"
const STEP_ID = "worker"
const GRANT_ID = "eval-worker-methodology-grant"

export default {
  id: "eval-worker-methodology-seed",
  async setup(ctx: any) {
    const seeded = new Set<string>()
    await ctx.session.hook("context", async (event: any) => {
      const sessionID = String(event?.sessionID ?? "").trim()
      if (!sessionID || event?.agent !== "worker" || seeded.has(sessionID)) return
      seeded.add(sessionID)

      const stateHome = String(process.env.XDG_STATE_HOME ?? "").trim()
      if (!stateHome) throw new Error("worker-methodology eval requires XDG_STATE_HOME")
      const db = new Database(join(stateHome, "loom", "execution-state.sqlite"), { create: true })
      db.run("CREATE TABLE IF NOT EXISTS kv (key TEXT PRIMARY KEY NOT NULL, value TEXT NOT NULL)")
      const marker = JSON.parse(await readFile(join(process.cwd(), ".loom", "project-id"), "utf8")) as { projectId?: string }
      const projectId = String(marker?.projectId ?? "").trim()
      if (!projectId) throw new Error("worker-methodology eval could not read Loom project marker")
      const scoped = (value: string) => `project/${projectId}/${value}`
      const put = db.prepare("INSERT INTO kv(key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value")
      const now = "2026-09-24T13:00:00.000Z"

      const seed = db.transaction(() => {
        put.run(scoped(`workflow/${WORKFLOW_ID}`), JSON.stringify({
          id: WORKFLOW_ID,
          projectId,
          revision: 0,
          anchor: `task:${WORKFLOW_ID}`,
          request: "Execute the already-authorized bounded Worker task.",
          createdBySession: "eval-parent",
          createdAt: now,
          steps: [{ id: STEP_ID, agent: "worker", kind: "work", dependsOn: [], status: "pending" }],
        }))
        put.run(scoped(`scope/${WORKFLOW_ID}/${STEP_ID}`), JSON.stringify({
          workflowId: WORKFLOW_ID,
          stepId: STEP_ID,
          write: ["src/**"],
        }))
        put.run(scoped(`dispatch-grant/${GRANT_ID}`), JSON.stringify({
          schemaVersion: 1,
          grantId: GRANT_ID,
          projectId,
          workflowId: WORKFLOW_ID,
          stepId: STEP_ID,
          expectedAgent: "worker",
          issuingParentSessionId: "eval-parent",
          createdAt: now,
          expiresAt: "2099-01-01T00:00:00.000Z",
        }))
      })
      seed()
      db.close()
    })
  },
}

export function endIndex(start: number, length: number) {
  return start + length
}

